package com.example.e2e.loggers.renamed;

import com.example.e2e.logging.Outcomes;

/**
 * Metric names of com.example.e2e.loggers.renamed, in one place: call sites call a member here and never name a metric.
 * Generated by logast (metrics.catalog). Rename or document members freely; logast keeps them and adds new
 * ones at the end.
 */
// logast:metrics-catalog
public final class RenamedMetrics {
    private RenamedMetrics() {
    }

    /** purge.step{outcome="failed"} +1. */
    public static void purgeStepFailed() {
        Outcomes.count("purge.step", "failed");
    }

    /** Registers this catalog's counters at 0 when the application has started: a series exists before the first event. */
    @org.springframework.stereotype.Component("com.example.e2e.loggers.renamed.RenamedMetrics.Registration")
    static final class Registration implements org.springframework.beans.factory.SmartInitializingSingleton {
        @Override
        public void afterSingletonsInstantiated() {
            Outcomes.register("purge.step", "failed");
        }
    }
}
